import {
  WALL_CENTER_Z,
  WALL_THICKNESS,
} from '@modules/door-model/components/parametric/ParametricWall';
import { useDoorMaterial } from '@modules/door-model/hooks/useDoorMaterials';
import { useGLTF } from '@react-three/drei';
import { FC, useEffect, useMemo } from 'react';
import * as THREE from 'three';
import { computeBoundsForSize, computeVScaleFactors } from './bounds';
import {
  findStakloNode,
  intMeshKeys,
  meshKeys,
  stakloMeshKeys,
} from './meshKeys';
import type { DoorPanelSize, GLTFResult } from './types';

interface DoorPanelProps {
  modelSrc: string;
  designId: string;
  size?: DoorPanelSize;
  targetWidth?: number;
  targetHeight?: number;
  materialId?: string;
  position?: [number, number, number];
  mirrored?: boolean;
}

/**
 * Renders the door panel 3D model for the selected design and size.
 * The model is auto-centered at the group's origin so frame / glass / wall
 * can be positioned relative to its geometric center.
 */
export const DoorPanel: FC<DoorPanelProps> = ({
  modelSrc,
  designId,
  size = 'L',
  targetWidth,
  targetHeight,
  materialId,
  position = [0, 0, 0],
  mirrored = false,
}) => {
  const { nodes, materials } = useGLTF(modelSrc) as unknown as GLTFResult;
  const ralMaterial = useDoorMaterial(materialId);
  const [panelX, panelY] = position;

  const panelBounds = useMemo(() => {
    return computeBoundsForSize(nodes, size, designId);
  }, [nodes, size, designId]);

  const centerOffset = panelBounds.center;
  const sourceWidth = panelBounds.sizeVec.x || 1;
  const sourceHeight = panelBounds.sizeVec.y || 1;
  const resolvedWidth = targetWidth ?? sourceWidth;
  const resolvedHeight = targetHeight ?? sourceHeight;

  // Scale the selected source model to requested target dimensions.
  const targetScaleX = resolvedWidth / sourceWidth;
  const targetScaleY = resolvedHeight / sourceHeight;

  // Scale the -V (front) mesh to match the -U (back) mesh dimensions first.
  const vScale = useMemo(() => {
    const { scaleX, scaleY, vCenter, uCenter } = computeVScaleFactors(
      nodes,
      size,
      designId,
    );
    return { scaleX, scaleY, vCenter, uCenter };
  }, [nodes, size, designId]);

  const [vKey, uKey] = meshKeys(designId, size);
  const [vIntKey, uIntKey] = intMeshKeys(designId, size);
  const vIntMesh = nodes[vIntKey] ?? null;
  const uIntMesh = nodes[uIntKey] ?? null;

  const [vStakloKey, uStakloKey] = stakloMeshKeys(designId, size);
  const vStakloMesh = nodes[vStakloKey] ?? findStakloNode(nodes, size, 'V');
  const uStakloMesh = nodes[uStakloKey] ?? findStakloNode(nodes, size, 'U');
  const halfTargetWidth = resolvedWidth / 2;
  const halfTargetHeight = resolvedHeight / 2;

  const clippingPlanes = useMemo(() => {
    // Keep panel clipped to requested width/height around its own center.
    const left = panelX - halfTargetWidth;
    const right = panelX + halfTargetWidth;
    const bottom = panelY - halfTargetHeight;
    const top = panelY + halfTargetHeight;

    const wallHalfDepth = WALL_THICKNESS / 2;
    const wallFrontZ = WALL_CENTER_Z + wallHalfDepth;
    const wallBackZ = WALL_CENTER_Z - wallHalfDepth;

    return [
      new THREE.Plane(new THREE.Vector3(1, 0, 0), -left),
      new THREE.Plane(new THREE.Vector3(-1, 0, 0), right),
      new THREE.Plane(new THREE.Vector3(0, 1, 0), -bottom),
      new THREE.Plane(new THREE.Vector3(0, -1, 0), top),
      new THREE.Plane(new THREE.Vector3(0, 0, 1), -wallBackZ),
      new THREE.Plane(new THREE.Vector3(0, 0, -1), wallFrontZ),
    ];
  }, [halfTargetHeight, halfTargetWidth, panelX, panelY]);

  const clippedMaterial = useMemo(() => {
    const base = ralMaterial ?? materials.Boja1;
    const material = base.clone();
    material.clippingPlanes = clippingPlanes;
    material.clipShadows = true;
    material.needsUpdate = true;
    return material;
  }, [clippingPlanes, ralMaterial, materials.Boja1]);

  useEffect(() => {
    return () => {
      clippedMaterial.dispose();
    };
  }, [clippedMaterial]);

  const clippedIntMaterial = useMemo(() => {
    const intNode = vIntMesh ?? uIntMesh;
    if (!intNode) return null;
    const base = Array.isArray(intNode.material)
      ? intNode.material[0]
      : intNode.material;
    const material = (base as THREE.MeshStandardMaterial).clone();
    material.clippingPlanes = clippingPlanes;
    material.clipShadows = true;
    material.needsUpdate = true;
    return material;
  }, [clippingPlanes, vIntMesh, uIntMesh]);

  useEffect(() => {
    return () => {
      clippedIntMaterial?.dispose();
    };
  }, [clippedIntMaterial]);

  const clippedStakloMaterial = useMemo(() => {
    const stakloNode = vStakloMesh ?? uStakloMesh;
    if (!stakloNode) return null;
    const base = Array.isArray(stakloNode.material)
      ? stakloNode.material[0]
      : stakloNode.material;
    const material = (base as THREE.MeshStandardMaterial).clone();
    material.clippingPlanes = clippingPlanes;
    material.clipShadows = true;
    material.needsUpdate = true;
    return material;
  }, [clippingPlanes, vStakloMesh, uStakloMesh]);

  useEffect(() => {
    return () => {
      clippedStakloMaterial?.dispose();
    };
  }, [clippedStakloMaterial]);

  return (
    <group position={position} scale={[mirrored ? -1 : 1, 1, 1]} dispose={null}>
      {/* Offset so the geometric center sits at origin */}
      <group
        position={[-centerOffset.x, -centerOffset.y, -centerOffset.z]}
        scale={[targetScaleX, targetScaleY, 1]}>
        {/* Front panel (-V) — scaled to match back panel dimensions, pivoting from its center */}
        <group
          position={[
            vScale.vCenter.x,
            vScale.vCenter.y,
            vScale.vCenter.z - 0.01,
          ]}>
          <group scale={[vScale.scaleX, vScale.scaleY, 1]}>
            <mesh
              castShadow
              receiveShadow
              geometry={nodes[vKey].geometry}
              material={clippedMaterial}
              position={[
                -vScale.vCenter.x,
                -vScale.vCenter.y,
                -vScale.vCenter.z,
              ]}
            />
            {vIntMesh && clippedIntMaterial && (
              <mesh
                receiveShadow
                geometry={vIntMesh.geometry}
                material={clippedIntMaterial}
                position={[
                  -vScale.vCenter.x,
                  -vScale.vCenter.y,
                  -vScale.vCenter.z,
                ]}
              />
            )}
            {vStakloMesh && clippedStakloMaterial && (
              <mesh
                castShadow
                geometry={vStakloMesh.geometry}
                material={clippedStakloMaterial}
                position={[
                  -vScale.vCenter.x,
                  -vScale.vCenter.y,
                  -vScale.vCenter.z,
                ]}
              />
            )}
          </group>
        </group>

        {/* Back panel (-U) — fits perfectly, no scaling needed */}
        <mesh
          castShadow
          receiveShadow
          geometry={nodes[uKey].geometry}
          material={clippedMaterial}
        />
        {uIntMesh && clippedIntMaterial && (
          <mesh
            receiveShadow
            geometry={uIntMesh.geometry}
            material={clippedIntMaterial}
          />
        )}
        {uStakloMesh && clippedStakloMaterial && (
          <mesh
            castShadow
            receiveShadow
            geometry={uStakloMesh.geometry}
            material={clippedStakloMaterial}
          />
        )}
      </group>
    </group>
  );
};
